SELECT DISTINCTROW RECLAMI2.[Record numero], RECLAMI2.[Reclamo numero], RECLAMI2.[Numero risposta], RECLAMI2.Data, RECLAMI2.Commessa, RECLAMI2.[Famiglia dei prodotti], RECLAMI2.[Kg reclamati], RECLAMI2.Motivazioni, RECLAMI2.Difetto, RECLAMI2.[Data risposta], RECLAMI2.Soluzione, RECLAMI2.Contabilità, RECLAMI2.Risposta, RECLAMI2.Commento, RECLAMI2.[Kg resi], RECLAMI2.Esterno, RECLAMI2.[Nota di credito], RECLAMI2.Accredito, RECLAMI2.[Ufficio 1], RECLAMI2.[Ufficio 2], RECLAMI2.[Ufficio 3], RECLAMI2.[Ufficio 4], RECLAMI2.[Ufficio 5], RECLAMI2.[Ufficio 6], DATI.CODPROD, DATI.DESPROD, DATI.FINITURA, DATI.SPESSORE, DATI.ALTEZZA, DATI.LARGHEZZA, DATI.ORIGINE, DATI.ORDINE, DATI.MACCHINA, DATI.NUMCOMM, DATI.ANCLI_1_DESCLI, DATI.RETE, DATI.CODCLI, DATI.ANCLI_DESCLI, DATI.DATAENT, DATI.QTAUSC, ([Data risposta]-[Data]) AS [Tempi risposta]
FROM DATI INNER JOIN RECLAMI2 ON DATI.NUMCOMM = RECLAMI2.Commessa
WHERE ((RECLAMI2.Difetto Like [Inserire il codice del difetto cercato]));
